sp_widget.client_script:
api.controller = function($window) {
  var c = this;
  c.cancel = function(m) {
    if (!$window.confirm('Cancel this reservation?')) return;
    c.server.get({ action: 'cancel', sys_id: m.sys_id });
  };
};

sp_widget.script:
(function() {
  var P = gs.getCurrentScopeName();
  var me = gs.getUserID();

  // Cancel: only the applicant can cancel their own scheduled meeting
  if (input && input.action == 'cancel') {
    var c = new GlideRecord(P + '_scheduled_meeting');
    if (c.get(input.sys_id) &&
        c.getValue('applicant') == me &&
        c.getValue('state') == 'scheduled') {
      c.setValue('state', 'cancelled');
      c.update();
    }
  }

  // List my scheduled meetings
  data.meetings = [];
  var g = new GlideRecord(P + '_scheduled_meeting');
  g.addQuery('applicant', me);
  g.addQuery('state', 'scheduled');
  g.orderBy('start_time');
  g.query();
  while (g.next()) {
    data.meetings.push({
      sys_id: g.getUniqueValue(),
      agenda: g.getValue('agenda'),
      room: g.getDisplayValue('meeting_room'),
      start: g.getDisplayValue('start_time'),
      end: g.getDisplayValue('end_time')
    });
  }
})();
